mapper.select:
SELECT A.* FROM ( select 'erro' as erroOrInfo, erro.WORKFLOW_ID as workflowId, erro.SALER_INS_NO as salerInsNo, null as salerRegistNo, null as salerInstCode, erro.SALER_NAME as salerName, erro.SALER_SEX as salerSex, null as salerBirthday, erro.SALER_CREDENT_TYPE as salerCredentType, null as salerOtherCredentName, null as salerCredentNo, null as salerAreaType, erro.SALER_ORG_CODE as salerOrgCode, null as salerDept, null as salerPosition, null as salerEduLevel, null as salerDegree, null as salerWorkStartYmd, null as salerFinanceStartYmd, null as salerStartYmd, null as salerLevle, null as salerCertificateType, null as salerChbTrainNo, null as salerRiskLevel, null as salerQualification, null as salerTel, null as salerMobile, null as salerMail, null as salerStatus, erro.DATA_DATE as dataDate, null as remark, 'A' as statusValid, erro.ERR_MSG as errMsg from CHB_SALER_IDEN_ERRODATA erro where 1=1
and erro.SALER_NAME like concat(concat('%',#{salerName,jdbcType=VARCHAR}),'%')
and erro.SALER_SEX = #{salerSex,jdbcType=VARCHAR}
and erro.STATUS = #{status,jdbcType=VARCHAR}
and erro.SALER_CREDENT_TYPE = #{salerCredentType,jdbcType=VARCHAR}
and erro.SALER_ORG_CODE like concat('%',concat(#{salerOrgCode,jdbcType=VARCHAR},'%'))
UNION ALL
select 'info' as erroOrInfo, null as workflowId, info.SALER_INS_NO as salerInsNo, info.SALER_REGIST_NO as salerRegistNo, info.SALER_INST_CODE as salerInstCode, info.SALER_NAME as salerName, info.SALER_SEX as salerSex, info.SALER_BIRTHDAY as salerBirthday, info.SALER_CREDENT_TYPE as salerCredentType, info.SALER_OTHER_CREDENT_NAME as salerOtherCredentName, info.SALER_CREDENT_NO as salerCredentNo, info.SALER_AREA_TYPE as salerAreaType, info.SALER_ORG_CODE as salerOrgCode, info.SALER_DEPT as salerDept, info.SALER_POSITION as salerPosition, info.SALER_EDU_LEVEL as salerEduLevel, info.SALER_DEGREE as salerDegree, info.SALER_WORK_START_YMD as salerWorkStartYmd, info.SALER_FINANCE_START_YMD as salerFinanceStartYmd, info.SALER_START_YMD as salerStartYmd, info.SALER_LEVLE as salerLevle, info.SALER_CERTIFICATE_TYPE as salerCertificateType, info.SALER_CHB_TRAIN_NO as salerChbTrainNo, info.SALER_RISK_LEVEL as salerRiskLevel, info.SALER_QUALIFICATION as salerQualification, info.SALER_TEL as salerTel, info.SALER_MOBILE as salerMobile, info.SALER_MAIL as salerMail, info.SALER_STATUS as salerStatus, info.DATA_DATE as dataDate, info.REMARK as remark, info.STATUS as statusValid, null as errMsg from CHB_SALER_IDEN_INFO info where 1=1
and info.SALER_NAME like concat(concat('%',#{salerName,jdbcType=VARCHAR}),'%')
and info.SALER_SEX = #{salerSex,jdbcType=VARCHAR}
and info.STATUS = #{status,jdbcType=VARCHAR}
and info.SALER_CREDENT_TYPE = #{salerCredentType,jdbcType=VARCHAR}
and info.SALER_ORG_CODE like concat('%',concat(#{salerOrgCode,jdbcType=VARCHAR},'%'))
) A ORDER BY A.statusValid DESC

select REGIST_BANK_CODE from CHB_ORG_REGIST_BANK_CODE
where
ORG_CODE = #{orgCode,jdbcType=VARCHAR}

